<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialSignCountAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialSignCountAccessor trait.
 *
 * Covers null default, string/VO assignment via withSignCount,
 * getSignCount/signCount accessors, and isSignCountChanged with/without original.
 */
class UserWebauthnCredentialSignCountAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSignCount creates a new instance with the SignCount set
     * from a string value, and getSignCount returns the primitive string.
     */
    public function testWithSignCountFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialSignCountAccessorUnitTest();

        // Act
        $result = $holder->withSignCount(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getSignCount());
    }
    /**
     * Asserts that withsignCount has access to the value object
     * from a string value, and getSignCount returns the primitive string.
     */
    public function testWithSignCountFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialSignCountAccessorUnitTest();

        // Act
        $result = $holder->withSignCount(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->signCount()->value());
    }
    public function testChangedSignCount(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialSignCountAccessorUnitTest()->withSignCount(1);
        $original = $holder->withSignCount(1);
        $same = $holder->withSignCount(1);
        $modified = $holder->withSignCount(2);

        // Act
        $withSame = $original->isSignCountChanged($same);
        $withDiferent = $original->isSignCountChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialSignCountAccessorUnitTest
{
    use UserWebauthnCredentialSignCountAccessor;
}
